export function graphql(source: "query GetTagFeed($locale: Locale!, $slug: String!, $page: Int!) {\n  feed(scope: tag, locale: $locale, slug: $slug, page: $page) {\n    redirect {\n      slug\n    }\n    caption\n    tag {\n      slug\n      name\n      articleCount\n    }\n    items {\n      ...FeedCard\n    }\n    pageInfo {\n      page\n      totalPages\n      hasNext\n    }\n  }\n}"): (typeof documents)["query GetTagFeed($locale: Locale!, $slug: String!, $page: Int!) {\n  feed(scope: tag, locale: $locale, slug: $slug, page: $page) {\n    redirect {\n      slug\n    }\n    caption\n    tag {\n      slug\n      name\n      articleCount\n    }\n    items {\n      ...FeedCard\n    }\n    pageInfo {\n      page\n      totalPages\n      hasNext\n    }\n  }\n}"];

export function graphql(source: string) {
  return (documents as any)[source] ?? {};
}

export type DocumentType<TDocumentNode extends DocumentNode<any, any>> = TDocumentNode extends DocumentNode<  infer TType,  any>  ? TType  : never;